from ledger import commit

def restore(snapshot, batches):
    # Handle legacy bare balance mappings (dict with account -> balance)
    # including a legacy account named "balances"
    if isinstance(snapshot, dict) and 'seen' not in snapshot:
        state = {'balances': dict(snapshot), 'seen': {}}
    else:
        state = {'balances': dict(snapshot['balances']), 'seen': dict(snapshot['seen'])}
    rejected = []
    for index, batch in enumerate(batches):
        try:
            state = commit(state, batch)
        except ValueError:
            rejected.append(index)
    return [state, rejected]
